import{_ as a,a0 as p,w as l,s as m,I as n,x as t,a1 as o,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux 移動或重命名文件/目錄－mv 的10個實用例子 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 移動或重命名文件/目錄－mv 的10個實用例子 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 移動或重命名文件/目錄－mv 的10個實用例子 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 移動或重命名文件/目錄－mv 的10個實用例子 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Moving or Rename File ／ Directory in Linux - 10 Practical mv Command Examples","title":"Linux 移動或重命名文件/目錄－mv 的10個實用例子","tag":"201403","desc":""},"relativePath":"201403/Moving or Rename File ／ Directory in Linux - 10 Practical mv Command Examples.md","filePath":"[post].md"}'),d={name:"201403/Moving or Rename File ／ Directory in Linux - 10 Practical mv Command Examples.md"};function g(f,e,c,x,h,u){const i=p("Link");return l(),m("div",null,[e[16]||(e[16]=n("h1",{id:"linux-移動或重命名文件-目錄-mv-的10個實用例子",tabindex:"-1"},[t("Linux 移動或重命名文件/目錄－mv 的10個實用例子 "),n("a",{class:"header-anchor",href:"#linux-移動或重命名文件-目錄-mv-的10個實用例子","aria-label":"Permalink to “Linux 移動或重命名文件/目錄－mv 的10個實用例子”"},"​")],-1)),n("p",null,[e[1]||(e[1]=t("熟悉了 ",-1)),o(i,{href:"http://linux.cn/article-2687-1.html"},{default:r(()=>[...e[0]||(e[0]=[t("複製命令",-1)])]),_:1}),e[2]||(e[2]=t("，下一個相關的命令就是 mv 命令。當你想要將文件從一個位置移動到另一個地方並且不想複製它，那麼",-1)),e[3]||(e[3]=n("strong",null,"mv 命令",-1)),e[4]||(e[4]=t("是完成這個任務的首選。",-1))]),e[17]||(e[17]=s(`<h3 id="初識-mv-命令" tabindex="-1">初識 mv 命令 <a class="header-anchor" href="#初識-mv-命令" aria-label="Permalink to “初識 mv 命令”">​</a></h3><p>mv 命令是一個與<strong>cp</strong>類似的命令，但是它<strong>並非</strong>創建文件或目錄的複製品/副本。不管你在使用什麼版本的Linux系統，mv 都默認安裝在你的Linux系統上了。來看一下 mv 命令在日常操作中的一些例子。</p><h4 id="_1-移動文件" tabindex="-1">1.移動文件 <a class="header-anchor" href="#_1-移動文件" aria-label="Permalink to “1.移動文件”">​</a></h4><p>移動文件時需要注意的是文件的源地址和目標地址<strong>必須不同</strong>。這裏有個例子，想要將<strong>file_1.txt</strong>文件從當前目錄移動到其它目錄，以<strong>/home/pungki/</strong>為例，語法應該如下：</p><pre><code>$ mv file_1.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv.png" alt="mv command"></p><p>如我們所見，當我們移動 file_txt 文件時，先前目錄的 file_1.txt 就<strong>被刪除了</strong>。</p><h4 id="_2-移動多個文件" tabindex="-1">2.移動多個文件 <a class="header-anchor" href="#_2-移動多個文件" aria-label="Permalink to “2.移動多個文件”">​</a></h4><p>如果想一次移動多個文件，我們可以將他們放在一行並用空格分開。</p><pre><code>$ mv file_2.txt file_3.txt file_4.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_multiple.png" alt="Move multiple files"></p><p>如果你的文件有規律可循的話那麼你就可以使用通配符。比如，為了移除所有以<strong>.txt</strong>為擴展名的文件，我們可以用下面的命令：</p><pre><code>$ mv *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_pattern.png" alt="Move using pattern"></p><h4 id="_3-移動目錄" tabindex="-1">3.移動目錄 <a class="header-anchor" href="#_3-移動目錄" aria-label="Permalink to “3.移動目錄”">​</a></h4><p>不同於複製命令，用 mv 命令移動目錄相當直接。移動目錄你可以使用不帶選項的 mv 命令。看下面的截圖就一目瞭然了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_directory.png" alt="Moving directory"></p><h4 id="_4-重命名文件或目錄" tabindex="-1">4.重命名文件或目錄 <a class="header-anchor" href="#_4-重命名文件或目錄" aria-label="Permalink to “4.重命名文件或目錄”">​</a></h4><p>我們也用 mv 命令來重命名文件或目錄。不過目標位置和源位置必須相同才可以。然後文件名必須不同。</p><p>假定我們當前所在目錄為<strong>/home/pungki/Documents</strong>，而我們想將<strong>file_1.txt重命名為file_2.txt</strong>。那麼命令應該如下：</p><pre><code>$ mv file_1.txt file_2.txt
</code></pre><p>如果是絕對路徑，它應該像下面這樣：</p><pre><code>$ mv /home/pungki/Documents/file_1.txt /home/pungki/Documents/file_2.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ren_file.png" alt="Renaming file"></p><h4 id="_5-重命名目錄" tabindex="-1">5. 重命名目錄 <a class="header-anchor" href="#_5-重命名目錄" aria-label="Permalink to “5. 重命名目錄”">​</a></h4><p>上一段的規則同樣適用於目錄。請看這個例子：</p><pre><code>$ mv directory_1/ directory_2/
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ren_directory.png" alt="Renaming directory"></p><h4 id="_6-打印移動信息" tabindex="-1">6. 打印移動信息 <a class="header-anchor" href="#_6-打印移動信息" aria-label="Permalink to “6. 打印移動信息”">​</a></h4><p>當你移動或重命名一大堆文件或目錄時，你可能會想在不去目標位置去查看的情況下知道你自己的命令是否成功地執行了。這就要用到<strong>-v</strong>選項了。</p><pre><code>$ mv -v *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_v.png" alt="mv with verbose mode"></p><p>該方法同樣適用於目錄。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_v_directory.png" alt="mv directory with verbose mode"></p><h4 id="_7-使用交互模式" tabindex="-1">7. 使用交互模式 <a class="header-anchor" href="#_7-使用交互模式" aria-label="Permalink to “7. 使用交互模式”">​</a></h4><p>當你將文件移動到其它位置，而那個位置恰好有同樣的文件，這時 mv 命令會覆蓋掉原來的文件。對於mv的這一行為一般不會有什麼提示。如果想產生一個關於覆蓋文件的提示，我們可以使用<strong>-i</strong>選項。（譯註：通常發行版會通過alias命令，將-i作為默認選項，所以會有提示。）</p><p>假設我們想將 file_1.txt 移動到 /home/pungki/office。同時，/home/pungki/office 目錄下已經有file_1.txt文件了。</p><pre><code>$ mv -i file_1.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_interactive.png" alt="mv with interactive mode"></p><p>這個提示會讓我們知道目標位置處file_1.txt的存在。如果我們按<strong>y</strong>鍵，那麼那個文件將會被刪除，否則不會。</p><h4 id="_8-使用更新選項" tabindex="-1">8. 使用更新選項 <a class="header-anchor" href="#_8-使用更新選項" aria-label="Permalink to “8. 使用更新選項”">​</a></h4><p>－i 選項會提示我們關於覆蓋文件的提示，而 －u 則只在源文件比目標文件新時才執行更新。讓我們看一看下面的例子：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_u.png" alt="Update only newer"></p><p>假如 file_1.txt 和 file_2.txt有如下特點：</p><pre><code>File_1.txt has 84 bytes file size and it last modified time is 12:00
File_2.txt has 0 bytes file size and it last modified time is 11:59
</code></pre><p>我們想將它們移動到 /home/pungki/office 目錄下。*<strong>但是目標地址</strong>已經有file_1.txt和file_2.txt了。</p><p>我們用下面的命令將file_1.txt 和file_2.txt從當前目錄移動到/home/pungki/office</p><pre><code>$ mv -uv *.txt /home/pungki/office
</code></pre><p>可以看到這些文件被移動了。能移動這些文件是因為它們最近的修改時間戳比 /home/pungki/office 目錄中的文件新。</p><h4 id="_9-不要覆蓋任何已存在的文件" tabindex="-1">9.不要覆蓋任何已存在的文件 <a class="header-anchor" href="#_9-不要覆蓋任何已存在的文件" aria-label="Permalink to “9.不要覆蓋任何已存在的文件”">​</a></h4><p>如果<strong>-i</strong>選項詢問我們是否要覆蓋文件，那麼 -n 選項將不會允許我們覆蓋任何已存在的文件。</p><p>繼續使用第8點中的例子，如果我們將<strong>-u 換成 -n</strong>同時加上<strong>-v</strong>選項，那麼我們會看到沒有任何文件移動到了 /home/pungki/office 目錄下。</p><pre><code>$ mv -vn *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_n.png" alt="No overwrite"></p><h4 id="_10-複製時創建備份" tabindex="-1">10. 複製時創建備份 <a class="header-anchor" href="#_10-複製時創建備份" aria-label="Permalink to “10. 複製時創建備份”">​</a></h4><p>默認情況下，移動文件將會覆蓋已存在的目標文件。但是如果我們移動錯了文件而目標文件已經被新的文件覆蓋了，這時應該怎麼辦才好呢？<strong>有沒有一種方法可以恢復之前的文件呢？答案是肯定的</strong>。我們可以用<strong>-b</strong>選項。該選項會在新文件覆蓋舊文件時將舊文件做備份。這裏我們還以第8點為例。</p><pre><code>$ mv -bv *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_b.png" alt="Backup option"></p><p>如截圖中所見，在 /home/pungki/office 目錄下出現了名為<strong>file_1.txt~ and file_2.txt~ 的文件。那個波浪符號（～）意味着</strong>這些文件是備份文件。從它們的屬性中我們可以看到，這些文件比file_1.txt和file_2.txt要舊。</p><h4 id="_11-無條件覆蓋已經存在的文件" tabindex="-1">11. 無條件覆蓋已經存在的文件 <a class="header-anchor" href="#_11-無條件覆蓋已經存在的文件" aria-label="Permalink to “11. 無條件覆蓋已經存在的文件”">​</a></h4><p>（譯註：這一節是譯者補充的，原文遺漏了這個重要選項）</p><p>當你希望無論如何都覆蓋已經存在的文件或目錄時，你可以使用 -f 選項。如果同時指定了 -f 選項和 -i 或 -n 選項，則 -f 選項會覆蓋它們——即不進行任何提示而覆蓋，所以，在使用此參數時，知道你在做什麼。</p><pre><code>$ mv -f *.txt /home/pungki/office
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>移動文件和目錄命令是Linux系統的基本命令。通常你可以通過<strong>man mv</strong> 或者 <strong>mv --help</strong>顯示mv的手冊頁以瞭解更多詳細信息。</p><hr>`,66)),n("p",null,[e[6]||(e[6]=t("via: ",-1)),o(i,{href:"http://linoxide.com/linux-command/mv-command-linux/"},{default:r(()=>[...e[5]||(e[5]=[t("http://linoxide.com/linux-command/mv-command-linux/",-1)])]),_:1})]),n("p",null,[e[9]||(e[9]=t("譯者：",-1)),o(i,{href:"https://github.com/Linchenguang"},{default:r(()=>[...e[7]||(e[7]=[t("Linchenguang",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:r(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創翻譯，",-1)),o(i,{href:"http://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const b=a(d,[["render",g]]);export{k as __pageData,b as default};
